 6	// For a given integer array, let's find the longest subesquence of 0s.
 7	// sz: size, pos: position.   a[pos..(pos+sz)] will be all zeros
 8	method longestZero(a: array<int>) returns (sz:int, pos:int)   
 9	    requires 1 <= a.Length
10	    ensures 0 <= sz <= a.Length
11	    ensures 0 <= pos < a.Length
12	    ensures pos + sz <= a.Length
13	    ensures forall i:int  :: pos <= i < pos + sz ==> a[i] == 0
14	    ensures forall i,j :: (0 <= i < j < a.Length && getSize(i, j) > sz) ==> exists k :: i <= k <= j && a[k] != 0
15	{
16	    var b := new int[a.Length];   // if b[i] == n, then a[i], a[i-1], ... a[i-n+1] will be all zeros and (i-n ==0 or a[i-n] !=0)
17	    if a[0] == 0
18	        {b[0] := 1;}
19	    else
20	        {b[0] := 0;}
21	
22	    var idx:int := 0;
23	    while idx < a.Length - 1    // idx <- 0 to a.Length - 2
24	        invariant 0 <= idx <= a.Length - 1
25	        invariant forall i:int :: 0 <= i <= (idx) - 1 ==>  0 <= b[i] <= a.Length
26	        invariant forall i:int :: 0 <= i <= idx ==> -1 <= i - b[i]
27	        invariant forall i:int :: 0 <= i <= idx ==> (forall j:int :: i-b[i] < j <= i ==> a[j] == 0) 
28	        invariant forall i:int :: 0 <= i <= idx ==> ( 0 <= i - b[i] ==> a[i - b[i]] != 0 )
29	    {
30	        if a[idx + 1] == 0
31	            { b[idx + 1] := b[idx] + 1; }
32	        else
33	            { b[idx + 1] := 0;}
34	
35	        idx := idx + 1;
36	    }
37	
38	
39	    idx := 1;
40	    sz := b[0];
41	    pos := 0;
42	    // Let's find maximum of array b. That is the desired sz.
43	    while idx < a.Length
44	        invariant 1 <= idx <= b.Length
45	
46	        invariant 0 <= sz <= a.Length
47	        invariant 0 <= pos < a.Length
48	        invariant pos + sz <= a.Length
49	
50	        invariant forall i:int :: 0 <= i < idx  ==> b[i] <= sz
51	        invariant forall i:int  :: pos <= i < pos + sz ==> a[i] == 0
52	        invariant forall i, j:int  :: (0 <= i < j < idx && getSize(i,j) > sz) ==>  a[j-b[j]] != 0
53	    {
54	        // find max
55	        if b[idx] > sz 
56	        { 
57	            sz := b[idx]; 
58	            pos := idx - b[idx] + 1;
59	        }
60	        idx := idx + 1;
61	    }
62	}
63	
64	
65	
66	method Main()
67	{
68	    var a := new int[10];
69	    forall i | 0 <= i < a.Length
70	        { a[i] := 0;}
71	    
72	    a[3] := 1;
73	    var sz, pos := longestZero(a);
74	    print a[..], "\n";
75	    print a[pos..(sz+pos)], "\n";
76	}
